# The following tests should pass:

import pytest
from.hotel import Hotel
from.hotel_repository import HotelRepository

@pytest.fixture
def hotel_repository():
    return HotelRepository()

@pytest.fixture
def hotel(hotel_repository):
    return HotelRepository().create_hotel("Hilton", "New York")

def test_search_by_city(hotel_repository, hotel):
    hotel_repository.add_hotel(hotel)
    result = hotel_repository.search_by_city("New York")
    assert result == [hotel]

def test_search_by_name(hotel_repository, hotel):
    hotel_repository.add_hotel(hotel)
    result = hotel_repository.search_by_name("Hilton")
    assert result == [hotel]

def test_search_by_street(hotel_repository, hotel):
    hotel_repository.add_hotel(hotel)
    result = hotel_repository.search_by_street("New York")
    assert result == [hotel]

def test_search_by_city_with_no_results(hotel_repository):
    result = hotel_repository.search_by_city("Moscow")
    assert result == []

def test_search_by_name_with_no_results(hotel_repository):
    result = hotel_repository.search_by_name("Hyatt")
    assert result == []

def test_search_by_street_with_no_results(hotel_repository):
    result = hotel_repository.search_by_street

